import fs from 'node:fs';
import path from 'node:path';
import { describe, expect, it } from 'vitest';
import {
  decisionOf,
  decisions,
  destinations,
  fieldErrors,
  firstFieldError,
  formatDate,
  hostOf,
  inboxStatusOf,
  inboxStatuses,
  itemStatusOf,
  itemStatuses,
  itemTypeLabel,
  itemTypes,
  objectiveStatuses,
  opportunityHref,
  unpadded,
} from './labels';
import { makeT, msg, tVi } from './i18n/translate';

/** `enum:` values of one component schema in lib/api/openapi.yaml (generated by drf-spectacular). */
const openapi = fs.readFileSync(path.join(__dirname, 'api/openapi.yaml'), 'utf8');
function apiEnum(name: string): string[] {
  const block = openapi.match(new RegExp(`\\n    ${name}:\\n      enum:\\n((?:      - .*\\n)+)`));
  if (!block) throw new Error(`${name} not found in openapi.yaml`);
  return block[1].trim().split('\n').map((l) => l.replace(/^\s*- /, '').trim());
}

describe('label maps cover the API enums', () => {
  // A new value on the Django side must get a Vietnamese label (and a colour) here.
  it.each([
    ['TypeEnum', itemTypes.map((x) => x.value)],
    ['ItemStatusEnum', itemStatuses.map((x) => x.value)],
    ['InboxStatusEnum', inboxStatuses.map((x) => x.value)],
    ['ObjectiveStatusEnum', Object.keys(objectiveStatuses)],
    ['OpportunityDecisionEnum', decisions.map((x) => x.value)],
  ])('%s', (name, values) => {
    expect([...values].sort()).toEqual(apiEnum(name).sort());
  });

  it('every destination the inbox tagger can suggest has a label', () => {
    // suggestedDestination is a plain string in the OpenAPI schema; the values live in the tagging schema.
    const tagging = fs.readFileSync(path.join(__dirname, '../../backend/inbox/tagging.py'), 'utf8');
    const literal = tagging.match(/destination: Literal\[([^\]]+)\]/);
    expect(literal, 'destination Literal in backend/inbox/tagging.py').not.toBeNull();
    const values = [...literal![1].matchAll(/"([^"]+)"/g)].map((m) => m[1]);
    expect(Object.keys(destinations).sort()).toEqual(values.sort());
  });

  it('labels are non-empty and unique within each list', () => {
    for (const list of [itemTypes, itemStatuses, inboxStatuses, decisions]) {
      const labels = list.map((x) => x.label.msgid);
      expect(labels.every((l) => l.trim().length > 0)).toBe(true);
      expect(new Set(labels).size).toBe(labels.length);
    }
  });
});

describe('lookups fall back instead of crashing', () => {
  it('itemTypeLabel returns the raw value for an unknown type', () => {
    expect(itemTypeLabel('book').msgid).toBe('Sách');
    expect(itemTypeLabel('podcast').msgid).toBe('podcast');
  });

  it('status and decision lookups fall back to the first entry', () => {
    expect(itemStatusOf('done').label.msgid).toBe('Xong');
    expect(itemStatusOf(undefined)).toBe(itemStatuses[0]);
    expect(itemStatusOf('archived')).toBe(itemStatuses[0]);
    expect(inboxStatusOf('later').label.msgid).toBe('Đọc sau');
    expect(inboxStatusOf('nope')).toBe(inboxStatuses[0]);
    expect(decisionOf('build').label.msgid).toBe('Làm');
    expect(decisionOf('')).toBe(decisions[0]);
  });
});

describe('hostOf', () => {
  it('strips www. only at the start', () => {
    expect(hostOf('https://www.coursera.org/learn/x')).toBe('coursera.org');
    expect(hostOf('https://news.www.example.com/')).toBe('news.www.example.com');
    expect(hostOf('http://127.0.0.1:8080/inbox/')).toBe('127.0.0.1');
  });

  it('returns an empty string for missing or relative URLs', () => {
    expect(hostOf(undefined)).toBe('');
    expect(hostOf('')).toBe('');
    expect(hostOf('/thu-vien/')).toBe('');
  });
});

describe('unpadded dates', () => {
  // en-GB pads numeric days and months ("08/11/2026"); the app writes them like vi-VN and lib/dates formatDay
  const enUtc = (o: Intl.DateTimeFormatOptions) => new Intl.DateTimeFormat('en-GB', { ...o, timeZone: 'UTC' });
  const at = Date.UTC(2026, 10, 8, 9, 5);

  it('drops the leading zero of the day and month only', () => {
    expect(unpadded(enUtc({ day: 'numeric', month: 'numeric', year: 'numeric' }), at)).toBe('8/11/2026');
    expect(unpadded(enUtc({ hour: '2-digit', minute: '2-digit' }), at)).toBe('09:05');
  });

  it('formatDate writes the same day in both languages and never throws', () => {
    const iso = '2026-03-05T12:00:00Z';
    expect(formatDate(iso, makeT('en', null))).toBe(formatDate(iso, tVi));
    expect(formatDate(iso, tVi)).toMatch(/^\d\/3\/2026$/);
    expect(formatDate('not a date', makeT('en', null))).toBe('Invalid Date');
  });
});

it('opportunityHref keeps the trailing slash before the query (trailingSlash: true)', () => {
  expect(opportunityHref(12)).toBe('/co-hoi/?id=12');
});

describe('fieldErrors', () => {
  it('returns null for anything that is not a DRF error object', () => {
    for (const body of [null, undefined, '', 'Bad Request', 400, {}, []]) expect(fieldErrors(body, tVi)).toBeNull();
  });

  it('translates DRF messages and names the field', () => {
    expect(fieldErrors({ title: ['This field is required.'] }, tVi, { title: msg('Tiêu đề') })).toBe(
      'Tiêu đề: Trường này là bắt buộc.',
    );
  });

  it('keeps the field key when no Vietnamese name is given', () => {
    expect(fieldErrors({ url: ['Enter a valid URL.'] }, tVi)).toBe('url: Nhập một URL hợp lệ.');
  });

  it('labels non_field_errors and detail as "Lỗi" (strings too, not only lists)', () => {
    expect(fieldErrors({ non_field_errors: ['Nope.'] }, tVi)).toBe('Lỗi: Nope.');
    expect(fieldErrors({ detail: 'Not found.' }, tVi)).toBe('Lỗi: Not found.');
  });

  it('joins several messages of one field and gives one line per field', () => {
    expect(
      fieldErrors(
        { title: ['This field may not be blank.', 'Ensure this field has no more than 300 characters.'], rating: ['A valid integer is required.'] },
        tVi,
        { title: msg('Tiêu đề'), rating: msg('Đánh giá') },
      ),
    ).toBe('Tiêu đề: Trường này không được bỏ trống. Tối đa 300 ký tự.\nĐánh giá: Cần một số nguyên.');
  });

  it('captures numbers, including negative and decimal bounds', () => {
    expect(firstFieldError({ x: ['Ensure this value is greater than or equal to -1.5.'] }, tVi)).toBe(
      'Giá trị phải lớn hơn hoặc bằng -1.5.',
    );
    expect(firstFieldError({ x: ['Ensure that there are no more than 2 decimal places.'] }, tVi)).toBe('Tối đa 2 chữ số thập phân.');
    expect(firstFieldError({ x: ['Ensure this field has at least 3 characters.'] }, tVi)).toBe('Ít nhất 3 ký tự.');
  });

  it('keeps the offending value in choice and pk messages', () => {
    expect(firstFieldError({ type: ['"podcast" is not a valid choice.'] }, tVi)).toBe('"podcast" không phải lựa chọn hợp lệ.');
    expect(firstFieldError({ item: ['Invalid pk "99" - object does not exist.'] }, tVi)).toBe('Không tìm thấy mục #99.');
  });

  it('collapses the long date-format and unique messages', () => {
    expect(
      firstFieldError({ decideBy: ['Date has wrong format. Use one of these formats instead: YYYY-MM-DD.'] }, tVi),
    ).toBe('Ngày sai định dạng, dùng YYYY-MM-DD.');
    expect(firstFieldError({ name: ['skill with this key already exists.'] }, tVi)).toBe('Đã có một mục như vậy.');
  });

  it('passes unknown and already-Vietnamese messages through unchanged', () => {
    expect(fieldErrors({ title: ['Trường này là bắt buộc.'] }, tVi)).toBe('title: Trường này là bắt buộc.');
    expect(firstFieldError({ x: ['This field is required. Really.'] }, tVi)).toBe('This field is required. Really.');
  });

  it('numbers ListField children from 1 ({ "0": [...] } -> #1)', () => {
    expect(
      fieldErrors({ tags: { '0': ['Ensure this field has no more than 50 characters.'], '2': ['This field may not be blank.'] } }, tVi, { tags: msg('Thẻ') }),
    ).toBe('Thẻ #1: Tối đa 50 ký tự.\nThẻ #3: Trường này không được bỏ trống.');
  });

  it('names nested serializer fields and list positions, skipping empty objects', () => {
    expect(
      fieldErrors(
        { scores: [{}, { value: ['Ensure this value is less than or equal to 10.'] }] },
        tVi,
        { scores: msg('Điểm'), value: msg('giá trị') },
      ),
    ).toBe('Điểm #2 giá trị: Giá trị phải nhỏ hơn hoặc bằng 10.');
  });

  it('ignores null and empty values but keeps numbers', () => {
    expect(fieldErrors({ a: null, b: '', c: undefined }, tVi)).toBeNull();
    expect(fieldErrors({ code: 42 }, tVi)).toBe('code: 42');
  });
});

describe('fieldErrors in English', () => {
  // Django answers English pages in English (backend/core/middleware.py): messages pass through, names translate
  const tEn = makeT('en', { 'Tiêu đề': 'Title', Lỗi: 'Error' });

  it('keeps DRF messages as they are and uses the English field names', () => {
    expect(fieldErrors({ title: ['This field is required.'] }, tEn, { title: msg('Tiêu đề') })).toBe(
      'Title: This field is required.',
    );
    expect(fieldErrors({ detail: 'Not found.' }, tEn)).toBe('Error: Not found.');
    expect(firstFieldError({ x: ['Ensure this field has at least 3 characters.'] }, tEn)).toBe(
      'Ensure this field has at least 3 characters.',
    );
  });
});

describe('firstFieldError', () => {
  it('returns the first translated message without the field name', () => {
    expect(firstFieldError({ title: ['This field is required.'], url: ['Enter a valid URL.'] }, tVi)).toBe(
      'Trường này là bắt buộc.',
    );
  });

  it('returns null for non-objects and bodies without messages', () => {
    expect(firstFieldError(null, tVi)).toBeNull();
    expect(firstFieldError('oops', tVi)).toBeNull();
    expect(firstFieldError({}, tVi)).toBeNull();
    expect(firstFieldError({ title: [] }, tVi)).toBeNull();
  });
});
